head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
    if (typeof id !== 'string') return id;
    var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
    if (!W.strictMode) id = id.replace(/mf_/g, '');
    if (C[U[id]]) return C[U[id]];
    var r; try { r = F(id); } catch (e) {}
    if (r == undefined && W.strictMode) {
        var P = W.strictModeFrame.id + '_';
        var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
        s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
        if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
    }
    return r == undefined ? id : r;
};
scwin.inputCalendar1_onviewchange = function(info) { //debugger;
    console.log(info.oldValue + "	" + info.newValue);
};
scwin.inputCalendar1_onyearselect = function(info) {};
scwin.__lostFocus = function() {
    $('input').blur();
}
scwin.checkVal1 = function() {
    return scwin.__getObj('inputCalendar1_input').value == checkYear;
}
scwin.checkVal2 = function() {
    return scwin.__getObj('inputCalendar2_input').value == checkYearMonth;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 12-Feb-2018
    window.currentTime = new Date();
    window.checkYear = currentTime.getFullYear() + 1;
    //var checkMonth = sprintf("%02d", currentTime.getMonth());
    window.checkMonth = currentTime.getMonth() + 1;
    window.checkYearMonth = "";
    if (checkMonth < 10) {
        checkYearMonth = String(checkYear) + "-" + "0" + String(checkMonth);
    } else {
        checkYearMonth = String(checkYear) + "-" + String(checkMonth);
    }
    //end
}
